COPY (SELECT system,origin,message,regexp_replace(path, '\[[0-9]+\]', '[*]', 'g') AS path,param_key, CASE WHEN path IN ('systemFrameNumber','mib/systemFrameNumber') THEN 'compteur courant, pas un paramètre (Q12)' WHEN (CASE WHEN path LIKE '%/logicalChannelConfig/%/logicalChannelGroup' THEN false WHEN regexp_replace(path, '\[[0-9]+\]', '[*]', 'g') IN ('systemInformationBlockType1/cellAccessRelatedInfo/cellIdentity','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mcc','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mnc','systemInformationBlockType1/cellAccessRelatedInfo/trackingAreaCode') THEN true ELSE COALESCE(is_identifier,false) END) THEN 'is_identifier=true (Q14 inclus)' ELSE 'padding ASN.1 explicite' END AS reason,count(*) n_occurrences FROM param_occurrence WHERE project_id='134af70a06eb' AND ((CASE WHEN path LIKE '%/logicalChannelConfig/%/logicalChannelGroup' THEN false WHEN regexp_replace(path, '\[[0-9]+\]', '[*]', 'g') IN ('systemInformationBlockType1/cellAccessRelatedInfo/cellIdentity','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mcc','systemInformationBlockType1/cellAccessRelatedInfo/plmn-IdentityList/[*]/plmn-Identity/mnc','systemInformationBlockType1/cellAccessRelatedInfo/trackingAreaCode') THEN true ELSE COALESCE(is_identifier,false) END) OR regexp_replace(path,'^.*/','') ~ '^(spare[0-9]*|dummy|reserved)$' OR path IN ('systemFrameNumber','mib/systemFrameNumber')) GROUP BY 1,2,3,4,5,6 ORDER BY 1,2,3,4) TO STDOUT WITH CSV HEADER;
